from itertools import combinations
G={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# candidate square and L tricells contained in a 2x2 window. color indices match missing corners: UL 2, LL 3, UR 4; missing LR unknown, use 5
pieces=[]
for r in range(3):
 for c in range(5):
  box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if box<=G: pieces.append((1,box))
  for missing,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
   cells=box-{missing}
   if cells<=G: pieces.append((col,cells))
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem,key=lambda p:sum(1 for _,s in pieces if p in s and s<=rem))
 for col,s in pieces:
  if x in s and s<=rem: rec(rem-s,chosen+[(col,s)])
rec(G,[])
print('solutions',len(sol))
for chosen in sol[:8]:
 out=[[0]*7 for _ in range(7)]
 for col,s in chosen:
  for r,c in s: out[r][c]=col
 print(chosen)
 print(*out,sep='\n')
